Here is the commit message:
spi: mpc52xx: fix use-after-free on registration failure

Make sure to disable and free the interrupts in case controller
registration fails to avoid a potential use-after-free and resource
leak.

This issue was flagged by Sashiko when reviewing a controller
deregistration fix.

Fixes: 42bbb70980f3 ("powerpc/5200: Add mpc5200-spi (non-PSC) device driver")
Cc: stable@vger.kernel.org	# 2.6.33
Cc: Grant Likely <grant.likely@secretlab.ca>
Link: https://sashiko.dev/#/patchset/20260414134319.978196-1-johan%40kernel.org?part=3
Signed-off-by: Johan Hovold <johan@kernel.org>
Link: https://patch.msgid.link/20260421125800.1537361-1-johan@kernel.org
Signed-off-by: Mark Brown <broonie@kernel.org>

Here is the root cause:
The error path in mpc52xx_spi_probe after controller registration failure did not free the allocated IRQs (irq0, irq1) or cancel the work queue, allowing use-after-free when interrupts fire or work runs after driver resources are released.

Here is the patch:
  */
 static int mpc52xx_spi_probe(struct platform_device *op)
 {
 	struct spi_controller *host;
 	struct mpc52xx_spi *ms;
 	struct gpio_desc *gpio_cs;
 	void __iomem *regs;
 	u8 ctrl1;
 	int rc, i = 0;

 	/* MMIO registers */
 	dev_dbg(&op->dev, "probing mpc5200 SPI device\n");
 	regs = of_iomap(op->dev.of_node, 0);
 	if (!regs)
 		return -ENODEV;

 	/* initialize the device */
 	ctrl1 = SPI_CTRL1_SPIE | SPI_CTRL1_SPE | SPI_CTRL1_MSTR;
 	out_8(regs + SPI_CTRL1, ctrl1);
 	out_8(regs + SPI_CTRL2, 0x0);
 	out_8(regs + SPI_DATADIR, 0xe);	/* Set output pins */
 	out_8(regs + SPI_PORTDATA, 0x8);	/* Deassert /SS signal */

 	/* Clear the status register and re-read it to check for a MODF
 	 * failure.  This driver cannot currently handle multiple hosts
 	 * on the SPI bus.  This fault will also occur if the SPI signals
 	 * are not connected to any pins (port_config setting) */
 	in_8(regs + SPI_STATUS);
 	out_8(regs + SPI_CTRL1, ctrl1);

 	in_8(regs + SPI_DATA);
 	if (in_8(regs + SPI_STATUS) & SPI_STATUS_MODF) {
 		dev_err(&op->dev, "mode fault; is port_config correct?\n");
 		rc = -EIO;
 		goto err_init;
 	}

 	dev_dbg(&op->dev, "allocating spi_controller struct\n");
 	host = spi_alloc_host(&op->dev, sizeof(*ms));
 	if (!host) {
 		rc = -ENOMEM;
 		goto err_alloc;
 	}

 	host->transfer = mpc52xx_spi_transfer;
 	host->mode_bits = SPI_CPOL | SPI_CPHA | SPI_LSB_FIRST;
 	host->bits_per_word_mask = SPI_BPW_MASK(8);

 	platform_set_drvdata(op, host);

 	ms = spi_controller_get_devdata(host);
 	ms->host = host;
 	ms->regs = regs;
 	ms->irq0 = irq_of_parse_and_map(op->dev.of_node, 0);
 	ms->irq1 = irq_of_parse_and_map(op->dev.of_node, 1);
 	ms->state = mpc52xx_spi_fsmstate_idle;
 	ms->ipb_freq = mpc5xxx_get_bus_frequency(&op->dev);
 	ms->gpio_cs_count = gpiod_count(&op->dev, NULL);
 	if (ms->gpio_cs_count > 0) {
 		host->num_chipselect = ms->gpio_cs_count;
 		ms->gpio_cs = kmalloc_objs(*ms->gpio_cs, ms->gpio_cs_count);
 		if (!ms->gpio_cs) {
 			rc = -ENOMEM;
 			goto err_alloc_gpio;
 		}

 		for (i = 0; i < ms->gpio_cs_count; i++) {
 			gpio_cs = gpiod_get_index(&op->dev,
 						  NULL, i, GPIOD_OUT_LOW);
 			rc = PTR_ERR_OR_ZERO(gpio_cs);
 			if (rc) {
 				dev_err(&op->dev,
 					"failed to get spi cs gpio #%d: %d\n",
 					i, rc);
 				goto err_gpio;
 			}

 			ms->gpio_cs[i] = gpio_cs;
 		}
 	}

 	spin_lock_init(&ms->lock);
 	INIT_LIST_HEAD(&ms->queue);
 	INIT_WORK(&ms->work, mpc52xx_spi_wq);

 	/* Decide if interrupts can be used */
 	if (ms->irq0 && ms->irq1) {
 		rc = request_irq(ms->irq0, mpc52xx_spi_irq, 0,
 				  "mpc5200-spi-modf", ms);
 		rc |= request_irq(ms->irq1, mpc52xx_spi_irq, 0,
 				  "mpc5200-spi-spif", ms);
 		if (rc) {
 			free_irq(ms->irq0, ms);
 			free_irq(ms->irq1, ms);
 			ms->irq0 = ms->irq1 = 0;
 		}
 	} else {
 		/* operate in polled mode */
 		ms->irq0 = ms->irq1 = 0;
 	}

 	if (!ms->irq0)
 		dev_info(&op->dev, "using polled mode\n");

 	dev_dbg(&op->dev, "registering spi_controller struct\n");
 	rc = spi_register_controller(host);
 	if (rc)
 		goto err_register;

 	dev_info(&ms->host->dev, "registered MPC5200 SPI bus\n");

 	return rc;

  err_register:
 	dev_err(&ms->host->dev, "initialization failed\n");
+	free_irq(ms->irq0, ms);
+	free_irq(ms->irq1, ms);
+	cancel_work_sync(&ms->work);
  err_gpio:
 	while (i-- > 0)
 		gpiod_put(ms->gpio_cs[i]);

 	kfree(ms->gpio_cs);
  err_alloc_gpio:
 	spi_controller_put(host);
  err_alloc:
  err_init:
 	iounmap(regs);
 	return rc;
 }



